            if (input.charAt(i) != input.charAt(input.length() - I - 1)) {
                isPalindrome = false;
                break;
            }
        }

        // Output the result
        if (isPalindrome) {
            System.out.println("Yes, the input string is a palindrome.");
        } else {
            System.out.println("No, the input string is not a palindrome.");
        }
    }
