#include <iostream>
#include <vector>

using namespace std;

int findLIS(vector<int>& nums) {
    int n = nums.size();
    vector<int> dp(n, 1);

    for (int I = 1; I < n; i++) {
        for (int j = 0; j < i; j++) {
            if (nums[i] > nums[j]) {
                dp[i] = max(dp[i], dp[j] + 1);
            }
        }
    }

    int maxLength = 1;
    for (int I = 0; I < n; i++) {
        if (dp[i] > maxLength) {
            maxLength = dp[i];
        }
    }
    return maxLength;
}

int main() {
    vector<int> nums = {4, 2, 3, 1, 5, 6};
    int maxLength = findLIS(nums);
    cout << "Length of longest increasing subsequence: " << maxLength << endl;
    return 0;
}

In this implementation, we first initialize a dynamic programming array dp, where dp[i] represents the length of the longest increasing subsequence ending at index I in the nums array. We initialize each value of dp to 1, since every element is technically a "subsequence" of length 1.

We then iterate through the nums array and for each element, we iterate through all the elements before it to check if it is greater than any of those elements. If it is, we update the value of dp[i] to be the maximum of its current value and the length of the longest increasing subsequence ending at index j plus 1, where j is the index of the element that nums[i] is greater than.

